<?php
$pageTitle=t('page_inventory_serials');
$ws_id=(int)($_SESSION['workshop_id']??0);
$can_serial=is_strict_admin()||has_permission('manage_inventory')||access_mode('inventory')==='editor';
if(!$can_serial){showToast(t('دسترسی ندارید'),'error');redirect('index.php?page=dashboard');}
$item_id=(int)($_GET['item_id']??$_POST['item_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
    $action=$_POST['action']??'';
    if($action==='add'){
        $serials=preg_split('/[\r\n,]+/',trim((string)$_POST['serials']));$n=0;
        foreach($serials as $serial){$serial=trim($serial);if($serial==='')continue;try{$st=$pdo->prepare("INSERT IGNORE INTO inventory_serials (workshop_id,item_id,serial_no,notes,created_by) VALUES (?,?,?,?,?)");$st->execute([$ws_id,$item_id,$serial,sanitize($_POST['notes']??''),$_SESSION['user_id']]);$n+=$st->rowCount();}catch(Throwable $e){}}
        operations_audit($pdo,(int)$_SESSION['user_id'],'add_serials','inventory_item',$item_id,$n.' سریال افزوده شد');showToast($n . ' ' . t('سریال ثبت شد.'));redirect('index.php?page=inventory&tab=serials&item_id='.$item_id);
    }
    if($action==='update'){
        $id=(int)$_POST['serial_id'];$status=$_POST['status']??'available';if(!in_array($status,['available','issued','repair','retired'],true))$status='available';$person_id=(int)($_POST['person_id']??0)?:null;$person_name='';if($person_id){$q=$pdo->prepare("SELECT full_name FROM users WHERE id=?");$q->execute([$person_id]);$person_name=(string)$q->fetchColumn();}
        $st=$pdo->prepare("UPDATE inventory_serials SET status=?,person_id=?,person_name=?,notes=? WHERE id=? AND workshop_id=?");$st->execute([$status,$person_id,$person_name,sanitize($_POST['notes']??''),$id,$ws_id]);operations_audit($pdo,(int)$_SESSION['user_id'],'update_serial','inventory_serial',$id,'وضعیت '.$status);showToast(t('سریال بروزرسانی شد.'));redirect('index.php?page=inventory&tab=serials&item_id='.$item_id);
    }
    if($action==='delete'){$id=(int)$_POST['serial_id'];$pdo->prepare("DELETE FROM inventory_serials WHERE id=? AND workshop_id=?")->execute([$id,$ws_id]);showToast(t('سریال حذف شد.'));redirect('index.php?page=inventory&tab=serials&item_id='.$item_id);}
}
$items=[];$serials=[];$personnel=[];$item=null;
try{$st=$pdo->prepare("SELECT * FROM inventory_items WHERE workshop_id=? AND status='active' ORDER BY name");$st->execute([$ws_id]);$items=$st->fetchAll();if($item_id){$st=$pdo->prepare("SELECT * FROM inventory_items WHERE id=? AND workshop_id=?");$st->execute([$item_id,$ws_id]);$item=$st->fetch();$st=$pdo->prepare("SELECT * FROM inventory_serials WHERE item_id=? AND workshop_id=? ORDER BY serial_no");$st->execute([$item_id,$ws_id]);$serials=$st->fetchAll();}$st=$pdo->prepare("SELECT u.id,u.full_name FROM users u JOIN workshop_personnel wp ON wp.user_id=u.id WHERE wp.workshop_id=? AND wp.status='active' ORDER BY u.full_name");$st->execute([$ws_id]);$personnel=$st->fetchAll();}catch(Throwable $e){}
include 'includes/header.php';
?>
<div class="d-flex justify-between align-center mb-4 animate-in"><h2>🔖 <?= t('page_inventory_serials') ?></h2></div>
<div class="tabs mb-4 animate-in inventory-tools-tabs"><a href="index.php?page=inventory&tab=stock" class="tab"><?= t('inv_stock') ?></a><a href="index.php?page=inventory&tab=active" class="tab"><?= t('خارج‌شده') ?></a><a href="index.php?page=inventory&tab=history" class="tab"><?= t('سابقه') ?></a><a href="index.php?page=inventory&tab=serials" class="tab active">🔖 <?= t('سریال ابزار') ?></a><a href="index.php?page=inventory&tab=purchases" class="tab">🛒 <?= t('page_purchases') ?></a><a href="index.php?page=inventory&tab=depreciation" class="tab">📉 <?= t('استهلاک') ?></a></div>
<div class="card mb-4 animate-in"><form method="get" class="d-flex gap-2 align-center"><input type="hidden" name="page" value="inventory_serials"><select name="item_id" class="form-control" style="max-width:320px" onchange="this.form.submit()"><option value=""><?= t('کالا') ?> <?= t('را') ?> <?= t('انتخاب کنید') ?></option><?php foreach($items as $it):?><option value="<?=$it['id']?>" <?=$item_id===$it['id']?'selected':''?>><?=htmlspecialchars($it['name'])?> · SKU: <?=htmlspecialchars($it['sku']?:'—')?></option><?php endforeach;?></select></form></div>
<?php if($item): ?>
<div class="stats-grid animate-in"><div class="stat-card"><div class="stat-icon primary"><i data-lucide="barcode"></i></div><div class="stat-info"><h3><?=count($serials)?></h3><p><?= t('سریال') ?> <?= t('ثبت') ?><?= t('‌شده') ?></p></div></div><div class="stat-card"><div class="stat-icon success"><i data-lucide="package-check"></i></div><div class="stat-info"><h3><?=count(array_filter($serials,fn($s)=>$s['status']==='available'))?></h3><p><?= t('inv_ready') ?></p></div></div><div class="stat-card"><div class="stat-icon warning"><i data-lucide="hand"></i></div><div class="stat-info"><h3><?=count(array_filter($serials,fn($s)=>$s['status']==='issued'))?></h3><p><?= t('inv_checkout') ?><?= t('‌شده') ?></p></div></div></div>
<div class="grid-2 mt-4"><section class="card"><div class="card-header"><h3 class="card-title"><?= t('btn_add') ?> <?= t('سریال') ?> <?= t('برای') ?> «<?=htmlspecialchars($item['name'])?>»</h3></div><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="add"><input type="hidden" name="item_id" value="<?=$item_id?>"><div class="form-group"><label class="form-label"><?= t('شماره') ?> <?= t('سریال') ?>‌<?= t('ها') ?></label><textarea name="serials" class="form-control" rows="6" required placeholder="<?= t('هر') ?> <?= t('سریال') ?> <?= t('در') ?> <?= t('یک خط') ?> <?= t('یا') ?> <?= t('با') ?> <?= t('کاما') ?> <?= t('جدا') ?> <?= t('شود') ?>"></textarea></div><div class="form-group"><label class="form-label"><?= t('wh_note') ?></label><input name="notes" class="form-control"></div><button class="btn btn-primary"><?= t('ثبت سریال‌ها') ?></button></form></section><section class="card"><div class="card-header"><h3 class="card-title"><?= t('btn_print') ?> <?= t('برچسب بارکد') ?></h3></div><p class="text-muted" style="font-size:12px;line-height:2"><?= t('برای') ?> <?= t('هر') ?> <?= t('ابزار') ?> <?= t('می‌توان یک') ?> <?= t('بارکد') ?> Code39 <?= t('btn_print') ?> <?= t('کرد') ?>. <?= t('شماره') ?> <?= t('سریال') ?> <?= t('یا') ?> SKU <?= t('در') ?> <?= t('برچسب') ?> <?= t('درج') ?> <?= t('می‌شود') ?>.</p><a class="btn btn-info" target="_blank" href="index.php?page=inventory_label_print&item_id=<?=$item_id?>">🖨 <?= t('btn_print') ?> <?= t('برچسب کالا') ?></a></section></div>
<div class="card mt-4 animate-in"><div class="table-container"><table><thead><tr><th><?= t('سریال') ?></th><th><?= t('wh_status') ?></th><th><?= t('نزد شخص') ?></th><th><?= t('wh_note') ?></th><th><?= t('wh_actions') ?></th></tr></thead><tbody><?php foreach($serials as $serial):?><tr><td><strong dir="ltr"><?=htmlspecialchars($serial['serial_no'])?></strong></td><td><span class="tag <?= $serial['status']==='available'?'tag-active':($serial['status']==='repair'?'tag-pending':'tag-warning') ?>"><?=['available'=>t('آماده'),'issued'=>t('تحویل‌شده'),'repair'=>t('تعمیر'),'retired'=>t('اسقاط')][$serial['status']]??$serial['status']?></span></td><td><?=htmlspecialchars($serial['person_name']?:'—')?></td><td><?=htmlspecialchars($serial['notes']?:'—')?></td><td><button class="btn btn-ghost btn-sm" onclick='editSerial(<?=js_arg($serial)?>)'>✏️</button><form method="post" style="display:inline" onsubmit="return confirm('<?= t('chat_delete') ?>')"><?= get_csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="item_id" value="<?=$item_id?>"><input type="hidden" name="serial_id" value="<?=$serial['id']?>"><button class="btn btn-ghost btn-sm text-danger">🗑</button></form></td></tr><?php endforeach;?><?php if(empty($serials)):?><tr><td colspan="5" class="text-center text-muted"><?= t('سریالی ثبت نشده است.') ?></td></tr><?php endif;?></tbody></table></div></div>
<div id="serialModal" class="modal-overlay hidden"><div class="modal glass-modal"><div class="modal-header"><h3 class="modal-title"><?= t('btn_edit') ?> <?= t('سریال') ?></h3><button class="modal-close" onclick="closeModal('serialModal')">✕</button></div><form method="post"><?= get_csrf_field() ?><input type="hidden" name="action" value="update"><input type="hidden" name="item_id" value="<?=$item_id?>"><input type="hidden" name="serial_id" id="serialId"><div class="modal-body"><p><?= t('سریال') ?>: <strong id="serialNo" dir="ltr"></strong></p><div class="form-group"><label class="form-label"><?= t('wh_status') ?></label><select name="status" id="serialStatus" class="form-control"><option value="available"><?= t('inv_ready') ?></option><option value="issued"><?= t('inv_checkout') ?><?= t('‌شده') ?></option><option value="repair"><?= t('inv_repair') ?></option><option value="retired"><?= t('اسقاط') ?></option></select></div><div class="form-group"><label class="form-label"><?= t('inv_checkout') ?><?= t('‌گیرنده') ?></label><select name="person_id" id="serialPerson" class="form-control"><option value="">—</option><?php foreach($personnel as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['full_name'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label"><?= t('wh_note') ?></label><input name="notes" id="serialNotes" class="form-control"></div></div><div class="modal-footer"><button class="btn btn-primary"><?= t('btn_save') ?></button></div></form></div></div>
<script>function editSerial(s){document.getElementById('serialId').value=s.id;document.getElementById('serialNo').textContent=s.serial_no;document.getElementById('serialStatus').value=s.status;document.getElementById('serialPerson').value=s.person_id||'';document.getElementById('serialNotes').value=s.notes||'';openModal('serialModal');}</script>
<?php endif; ?>
